list.definition:
SELECT concat(to_char(date AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD'), '#', date::text) AS formatted_date
FROM ${table}
WHERE $__timeFilter(date) AND ${env}
GROUP BY formatted_date
ORDER BY SUM(pod_count * p95_pod_load) DESC
LIMIT 1

